function patternButterfly(n) {
  let rows = [];
  // Top half
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < i + 1; j++) row += '*';
    for (let j = 0; j < 2 * (n - 1 - i); j++) row += ' ';
    for (let j = 0; j < i + 1; j++) row += '*';
    rows.push(row);
  }
  // Bottom half
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < n - i; j++) row += '*';
    for (let j = 0; j < 2 * i; j++) row += ' ';
    for (let j = 0; j < n - i; j++) row += '*';
    rows.push(row);
  }
  return rows.join('\n');
}

