function patternButterfly(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    const stars = '*'.repeat(i + 1);
    const spaces = ' '.repeat(2 * (n - 1 - i));
    rows.push(stars + spaces + stars);
  }
  for (let i = 0; i < n; i++) {
    const stars = '*'.repeat(n - i);
    const spaces = ' '.repeat(2 * i);
    rows.push(stars + spaces + stars);
  }
  return rows.join('\n');
}
